use std::iter::Peekable;
use std::ops::Add;

use super::{Keyword, Lexer, Token, ast};
use crate::errinput;
use crate::error::Result;
use crate::sql::types::DataType;

pub struct Parser<'a> {
    pub lexer: Peekable<Lexer<'a>>,
}

impl Parser<'_> {
    pub fn parse(statement: &str) -> Result<ast::Statement> {
        let mut parser = Parser::new(statement);
        let stmt = parser.parse_statement()?;
        parser.skip(Token::Semicolon);
        if parser.lexer.next().is_some() {
            return errinput!("unexpected tokens after statement");
        }
        Ok(stmt)
    }

    #[cfg(test)]
    pub fn parse_expr(expr: &str) -> Result<ast::Expression> {
        let mut parser = Parser::new(expr);
        let expr = parser.parse_expression()?;
        if parser.lexer.next().is_some() {
            return errinput!("unexpected tokens after expression");
        }
        Ok(expr)
    }

    fn new(input: &str) -> Parser<'_> {
        Parser { lexer: Lexer::new(input).peekable() }
    }

    fn next(&mut self) -> Result<Token> {
        match self.lexer.next() {
            Some(Ok(t)) => Ok(t),
            Some(Err(e)) => Err(e),
            None => errinput!("unexpected end of input"),
        }
    }

    fn next_ident(&mut self) -> Result<String> {
        match self.next()? {
            Token::Ident(s) => Ok(s),
            Token::Keyword(k) => Ok(k.to_string().to_lowercase()),
            t => errinput!("expected identifier, found {t}"),
        }
    }

    fn next_if(&mut self, predicate: impl Fn(&Token) -> bool) -> Option<Token> {
        if let Some(Ok(token)) = self.lexer.peek() {
            if predicate(token) {
                self.lexer.next();
                return Some(token.clone());
            }
        }
        None
    }

    fn next_if_map<T>(&mut self, f: impl Fn(&Token) -> Option<T>) -> Option<T> {
        if let Some(Ok(token)) = self.lexer.peek() {
            if let Some(result) = f(token) {
                self.lexer.next();
                return Some(result);
            }
        }
        None
    }

    fn next_if_keyword(&mut self) -> Option<Keyword> {
        self.next_if_map(|t| match t { Token::Keyword(k) => Some(*k), _ => None })
    }

    fn next_is(&mut self, token: Token) -> bool {
        self.next_if(|t| *t == token).is_some()
    }

    fn expect(&mut self, expect: Token) -> Result<()> {
        if !self.next_is(expect.clone()) {
            return errinput!("expected {expect}, found {}", self.peek()?.unwrap_or(&Token::Semicolon));
        }
        Ok(())
    }

    fn skip(&mut self, token: Token) {
        self.next_is(token);
    }

    fn peek(&mut self) -> Result<Option<&Token>> {
        Ok(self.lexer.peek().and_then(|r| r.as_ref().ok()))
    }

    fn parse_statement(&mut self) -> Result<ast::Statement> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Begin => self.parse_begin(),
                Keyword::Commit => self.parse_commit(),
                Keyword::Rollback => self.parse_rollback(),
                Keyword::Explain => self.parse_explain(),
                Keyword::Create => self.parse_create_table(),
                Keyword::Drop => self.parse_drop_table(),
                Keyword::Delete => self.parse_delete(),
                Keyword::Insert => self.parse_insert(),
                Keyword::Update => self.parse_update(),
                Keyword::Select => self.parse_select(),
                _ => errinput!("unexpected keyword {kw}"),
            }
        } else {
            errinput!("expected SQL statement, found {}", self.peek()?.unwrap_or(&Token::Semicolon))
        }
    }

    fn parse_begin(&mut self) -> Result<ast::Statement> {
        let mut read_only = false;
        let mut as_of: Option<u64> = None;
        if self.next_is(Keyword::Read.into()) {
            read_only = true;
            if self.next_is(Keyword::Only.into()) {
                self.skip(Token::OpenParen);
            }
        }
        if self.next_is(Keyword::As.into()) {
            self.expect(Token::OpenParen)?;
            if let Token::Number(s) = self.next()? {
                as_of = Some(s.parse::<u64>().map_err(|_| errinput!("invalid version number {s}"))?);
            }
            self.expect(Token::CloseParen)?;
        }
        Ok(ast::Statement::Begin { read_only, as_of })
    }

    fn parse_commit(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Commit)
    }

    fn parse_rollback(&mut self) -> Result<ast::Statement> {
        Ok(ast::Statement::Rollback)
    }

    fn parse_explain(&mut self) -> Result<ast::Statement> {
        let stmt = self.parse_statement()?;
        Ok(ast::Statement::Explain(Box::new(stmt)))
    }

    fn parse_create_table(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::Table.into())?;
        let name = self.next_ident()?;
        self.expect(Token::OpenParen)?;
        let mut columns = Vec::new();
        loop {
            columns.push(self.parse_create_table_column()?);
            if !self.next_is(Token::Comma) { break; }
        }
        self.expect(Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = match self.next_if_keyword() {
            Some(Keyword::Bool) | Some(Keyword::Boolean) => DataType::Boolean,
            Some(Keyword::Int) | Some(Keyword::Integer) => DataType::Integer,
            Some(Keyword::Float) => DataType::Float,
            Some(Keyword::String) | Some(Keyword::Text) | Some(Keyword::Varchar) => DataType::String,
            Some(kw) => return errinput!("unexpected datatype keyword {kw}"),
            None => return errinput!("expected datatype"),
        };
        let mut primary_key = false;
        let mut nullable = None;
        let mut default = None;
        let mut unique = false;
        let mut index = false;
        let mut references = None;
        loop {
            if self.next_is(Keyword::Primary.into()) {
                self.expect(Keyword::Key.into())?;
                primary_key = true;
            } else if self.next_is(Keyword::Not.into()) {
                self.expect(Keyword::Null.into())?;
                nullable = Some(false);
            } else if self.next_is(Keyword::Null.into()) {
                nullable = Some(true);
            } else if self.next_is(Keyword::Default.into()) {
                default = Some(self.parse_expression()?);
            } else if self.next_is(Keyword::Unique.into()) {
                unique = true;
            } else if self.next_is(Keyword::Index.into()) {
                index = true;
            } else if self.next_is(Keyword::References.into()) {
                references = Some(self.next_ident()?);
            } else {
                break;
            }
        }
        Ok(ast::Column { name, datatype, primary_key, nullable, default, unique, index, references })
    }

    fn parse_drop_table(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::Table.into())?;
        let if_exists = self.next_is(Keyword::If.into());
        if if_exists {
            self.expect(Keyword::Exists.into())?;
        }
        let name = self.next_ident()?;
        Ok(ast::Statement::DropTable { name, if_exists })
    }

    fn parse_delete(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::From.into())?;
        let table = self.next_ident()?;
        let mut r#where = None;
        if self.next_is(Keyword::Where.into()) {
            r#where = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Delete { table, r#where })
    }

    fn parse_insert(&mut self) -> Result<ast::Statement> {
        self.expect(Keyword::Into.into())?;
        let table = self.next_ident()?;
        let mut columns = None;
        if self.next_is(Token::OpenParen) {
            columns = Some(self.parse_column_list()?);
        }
        self.expect(Keyword::Values.into())?;
        let mut values = Vec::new();
        loop {
            values.push(self.parse_value_list()?);
            if !self.next_is(Token::Comma) { break; }
        }
        Ok(ast::Statement::Insert { table, columns, values })
    }

    fn parse_update(&mut self) -> Result<ast::Statement> {
        let table = self.next_ident()?;
        self.expect(Keyword::Set.into())?;
        let mut set = std::collections::BTreeMap::new();
        loop {
            let col = self.next_ident()?;
            self.expect(Token::Equal)?;
            let expr = if self.next_is(Keyword::Default.into()) {
                None
            } else {
                Some(self.parse_expression()?)
            };
            set.insert(col, expr);
            if !self.next_is(Token::Comma) { break; }
        }
        let mut r#where = None;
        if self.next_is(Keyword::Where.into()) {
            r#where = Some(self.parse_expression()?);
        }
        Ok(ast::Statement::Update { table, set, r#where })
    }

    fn parse_select(&mut self) -> Result<ast::Statement> {
        let select = self.parse_select_clause()?;
        let from = self.parse_from_clause()?;
        let r#where = self.parse_where_clause()?;
        let group_by = self.parse_group_by_clause()?;
        let having = self.parse_having_clause()?;
        let order_by = self.parse_order_by_clause()?;
        let offset = self.parse_offset_clause()?;
        let limit = self.parse_limit_clause()?;
        Ok(ast::Statement::Select { select, from, r#where, group_by, having, order_by, offset, limit })
    }

    fn parse_select_clause(&mut self) -> Result<Vec<(ast::Expression, Option<String>)>> {
        let mut select = Vec::new();
        loop {
            let expr = self.parse_expression()?;
            let mut alias = None;
            if self.next_is(Keyword::As.into()) {
                alias = Some(self.next_ident()?);
            } else if let ast::Expression::Column(_, name) = &expr {
                if name != "*" {
                    alias = Some(name.clone());
                }
            }
            select.push((expr, alias));
            if !self.next_is(Token::Comma) { break; }
        }
        Ok(select)
    }

    fn parse_from_clause(&mut self) -> Result<Vec<ast::From>> {
        if !self.next_is(Keyword::From.into()) {
            return Ok(Vec::new());
        }
        let mut from = Vec::new();
        loop {
            let table = self.parse_from_table()?;
            if let Some(join_type) = self.parse_from_join()? {
                let right = self.parse_from_table()?;
                let mut predicate = None;
                if self.next_is(Keyword::On.into()) {
                    predicate = Some(self.parse_expression()?);
                }
                from.push(ast::From::Join { left: Box::new(table), right: Box::new(right), r#type: join_type, predicate });
            } else {
                from.push(table);
            }
            if !self.next_is(Token::Comma) { break; }
        }
        Ok(from)
    }

    fn parse_from_table(&mut self) -> Result<ast::From> {
        let name = self.next_ident()?;
        let mut alias = None;
        if self.next_is(Keyword::As.into()) {
            alias = Some(self.next_ident()?);
        } else if let Some(kw) = self.next_if_keyword() {
            if !matches!(kw, Keyword::Join | Keyword::Inner | Keyword::Left | Keyword::Right | Keyword::Cross | Keyword::On | Keyword::Where | Keyword::Group | Keyword::Having | Keyword::Order | Keyword::Limit | Keyword::Offset) {
                alias = Some(kw.to_string().to_lowercase());
            } else {
                self.lexer.next();
            }
        }
        Ok(ast::From::Table { name, alias })
    }

    fn parse_from_join(&mut self) -> Result<Option<ast::JoinType>> {
        if let Some(kw) = self.next_if_keyword() {
            match kw {
                Keyword::Inner => Ok(Some(ast::JoinType::Inner)),
                Keyword::Left => Ok(Some(ast::JoinType::Left)),
                Keyword::Right => Ok(Some(ast::JoinType::Right)),
                Keyword::Cross => Ok(Some(ast::JoinType::Cross)),
                _ => { self.lexer.next(); Ok(None) },
            }
        } else {
            Ok(None)
        }
    }

    fn parse_where_clause(&mut self) -> Result<Option<ast::Expression>> {
        if !self.next_is(Keyword::Where.into()) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    fn parse_group_by_clause(&mut self) -> Result<Vec<ast::Expression>> {
        if !self.next_is(Keyword::Group.into()) {
            return Ok(Vec::new());
        }
        self.expect(Keyword::By.into())?;
        let mut group_by = Vec::new();
        loop {
            group_by.push(self.parse_expression()?);
            if !self.next_is(Token::Comma) { break; }
        }
        Ok(group_by)
    }

    fn parse_having_clause(&mut self) -> Result<Option<ast::Expression>> {
        if !self.next_is(Keyword::Having.into()) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    fn parse_order_by_clause(&mut self) -> Result<Vec<(ast::Expression, ast::Direction)>> {
        if !self.next_is(Keyword::Order.into()) {
            return Ok(Vec::new());
        }
        self.expect(Keyword::By.into())?;
        let mut order_by = Vec::new();
        loop {
            let expr = self.parse_expression()?;
            let mut dir = ast::Direction::Ascending;
            if self.next_is(Keyword::Asc.into()) {
                dir = ast::Direction::Ascending;
            } else if self.next_is(Keyword::Desc.into()) {
                dir = ast::Direction::Descending;
            }
            order_by.push((expr, dir));
            if !self.next_is(Token::Comma) { break; }
        }
        Ok(order_by)
    }

    fn parse_limit_clause(&mut self) -> Result<Option<ast::Expression>> {
        if !self.next_is(Keyword::Limit.into()) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    fn parse_offset_clause(&mut self) -> Result<Option<ast::Expression>> {
        if !self.next_is(Keyword::Offset.into()) {
            return Ok(None);
        }
        Ok(Some(self.parse_expression()?))
    }

    fn parse_expression(&mut self) -> Result<ast::Expression> {
        self.parse_expression_at(0)
    }

    fn parse_expression_at(&mut self, min_precedence: Precedence) -> Result<ast::Expression> {
